def storePassword(userName,Password):  
  hasher = hashlib.new('md5') 
  hasher.update(Password)

def getHash(password): 
  hash = pbkdf2_hmac('sha256', password, b'D8VxSmTZt2E2YV454mkqAY5e', 100000)  
  return hash

